const VAPID_PUBLIC_KEY = "BMr4ZWTwS2DgL12mxYFjLM9rmnljnJpY_tsFtWtKxgS2d_z36lcg3sLfIQfOFbX1Tw0ITNG3pB4hJeGI-YEZFHE";
const SERVICE_WORKER_URL = "/sw.js?v=337";

const PUSH_VAPID_MARKER_KEY = "bariq_push_vapid_public_key";
const PUSH_ENABLED_KEY = "bariq_push_enabled";
const PUSH_MIGRATION_LOCK_KEY = "bariq_push_migrating";

function urlBase64ToUint8Array(value) {
    const padded = value + "=".repeat((4 - value.length % 4) % 4);
    const base64 = padded.replace(/-/g, "+").replace(/_/g, "/");
    const rawData = window.atob(base64);
    return Uint8Array.from([...rawData].map(char => char.charCodeAt(0)));
}

function samePushApplicationKey(subscription, publicKey) {
    try {
        const currentKey = subscription?.options?.applicationServerKey;

        // لو المتصفح لا يعرض المفتاح، نعتمد كذلك على marker محفوظ محلياً.
        if (!currentKey) {
            return localStorage.getItem(PUSH_VAPID_MARKER_KEY) === publicKey;
        }

        const actual = new Uint8Array(currentKey);
        const expected = urlBase64ToUint8Array(publicKey);

        return actual.length === expected.length &&
            actual.every((value, index) => value === expected[index]);
    } catch (err) {
        console.warn("Failed to compare push application key:", err);
        return false;
    }
}

function normalizeUaePhone(value) {
    let digits = String(value || "").replace(/\D/g, "");

    if (digits.startsWith("00971")) digits = digits.slice(2);
    if (digits.startsWith("971")) digits = digits.slice(3);
    if (digits.startsWith("0")) digits = digits.slice(1);

    digits = digits.slice(0, 9);
    return digits ? "+971" + digits : "";
}

function getCurrentPushLanguage() {
    return (
        localStorage.getItem("lang") ||
        document.documentElement.lang ||
        "ar"
    ) === "en" ? "en" : "ar";
}

function sendPushLanguageToServiceWorker() {
    try {
        const lang = getCurrentPushLanguage();

        navigator.serviceWorker?.ready
            .then(registration => {
                registration.active?.postMessage({
                    type: "SET_PUSH_LANG",
                    lang
                });
            })
            .catch(() => {});

        navigator.serviceWorker?.controller?.postMessage({
            type: "SET_PUSH_LANG",
            lang
        });
    } catch (_) {}
}

async function registerSW() {
    if (!("serviceWorker" in navigator)) return null;

    try {
        const registration = await navigator.serviceWorker.register(
            SERVICE_WORKER_URL,
            { updateViaCache: "none" }
        );

        registration.update().catch(() => {});
        sendPushLanguageToServiceWorker();

        // بعد تجهيز الـSW مباشرة نفحص هل الاشتراك قديم ونهاجره تلقائياً.
        ensureCurrentVapidSubscription().catch(err => {
            console.warn("Automatic VAPID migration failed:", err);
        });

        return registration;
    } catch (err) {
        console.warn("Service worker registration failed:", err);
        return null;
    }
}

window.addEventListener("storage", event => {
    if (event.key === "lang") {
        sendPushLanguageToServiceWorker();
    }
});

window.addEventListener(
    "bariq:languagechange",
    sendPushLanguageToServiceWorker
);

async function deleteSubscriptionFromSupabase(endpoint) {
    if (!endpoint) return false;

    const SUPABASE_ANON_KEY =
        "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImtubGVlaGpqZWpmZW9iY21wd253Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODQwMjk1NzAsImV4cCI6MjA5OTYwNTU3MH0.Q5Peb8CXDYNSPtQJGK6meij4vFRfOUq9qFz4rHBXE8E";

    try {
        const response = await fetch(
            "https://knleehjjejfeobcmpwnw.supabase.co/rest/v1/push_subscriptions?endpoint=eq." +
                encodeURIComponent(endpoint),
            {
                method: "DELETE",
                headers: {
                    apikey: SUPABASE_ANON_KEY,
                    Authorization: "Bearer " + SUPABASE_ANON_KEY,
                    Prefer: "return=minimal"
                }
            }
        );

        if (!response.ok) {
            console.warn(
                "Could not remove old push subscription from Supabase:",
                response.status,
                await response.text().catch(() => "")
            );
        }

        return response.ok;
    } catch (err) {
        console.warn("Failed deleting old subscription:", err);
        return false;
    }
}

async function ensureCurrentVapidSubscription() {
    if (
        !("serviceWorker" in navigator) ||
        !("PushManager" in window) ||
        !("Notification" in window)
    ) {
        return null;
    }

    // لا نطلب Permission تلقائياً. الهجرة التلقائية تعمل فقط لمن سبق ووافق.
    if (Notification.permission !== "granted") {
        return null;
    }

    // حماية من تشغيل الهجرة مرتين مع بعض.
    if (window.__bariqPushMigrationPromise) {
        return window.__bariqPushMigrationPromise;
    }

    window.__bariqPushMigrationPromise = (async () => {
        const registration = await navigator.serviceWorker.ready;
        let subscription = await registration.pushManager.getSubscription();

        if (!subscription) {
            // لو المستخدم فعّل الإشعارات سابقاً داخل بريق، نعيد إنشاء الاشتراك تلقائياً.
            if (localStorage.getItem(PUSH_ENABLED_KEY) === "1") {
                subscription = await registration.pushManager.subscribe({
                    userVisibleOnly: true,
                    applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY)
                });

                const saved = await saveSubscriptionToSupabase(subscription);

                if (saved) {
                    localStorage.setItem(PUSH_VAPID_MARKER_KEY, VAPID_PUBLIC_KEY);
                    localStorage.setItem(PUSH_ENABLED_KEY, "1");
                    console.log("Push subscription restored with current VAPID key.");
                    return subscription;
                }

                return null;
            }

            return null;
        }

        const markerMatches =
            localStorage.getItem(PUSH_VAPID_MARKER_KEY) === VAPID_PUBLIC_KEY;

        const browserKeyMatches =
            samePushApplicationKey(subscription, VAPID_PUBLIC_KEY);

        // اشتراك سليم بالفعل: فقط حدّث بيانات الهاتف/الإيميل/اللغة في Supabase.
        if (markerMatches && browserKeyMatches) {
            const saved = await saveSubscriptionToSupabase(subscription);

            if (saved) {
                localStorage.setItem(PUSH_ENABLED_KEY, "1");
            }

            return subscription;
        }

        console.log("Old VAPID subscription detected. Migrating automatically...");

        const oldEndpoint = subscription.endpoint;

        // نحذف الصف القديم من قاعدة البيانات أولاً لتجنب بقاء اشتراك غير صالح.
        await deleteSubscriptionFromSupabase(oldEndpoint).catch(() => {});

        try {
            await subscription.unsubscribe();
        } catch (err) {
            console.warn("Could not unsubscribe stale subscription:", err);
        }

        subscription = await registration.pushManager.subscribe({
            userVisibleOnly: true,
            applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY)
        });

        const saved = await saveSubscriptionToSupabase(subscription);

        if (!saved) {
            console.error(
                "New VAPID subscription was created but could not be persisted."
            );
            return null;
        }

        localStorage.setItem(PUSH_VAPID_MARKER_KEY, VAPID_PUBLIC_KEY);
        localStorage.setItem(PUSH_ENABLED_KEY, "1");

        console.log("VAPID migration completed successfully.");
        return subscription;
    })();

    try {
        return await window.__bariqPushMigrationPromise;
    } finally {
        window.__bariqPushMigrationPromise = null;
    }
}

async function refreshCurrentPushSubscriptionLanguage() {
    if (!("serviceWorker" in navigator) || !("PushManager" in window)) {
        return;
    }

    try {
        const registration = await navigator.serviceWorker.ready;
        const subscription = await registration.pushManager.getSubscription();

        if (!subscription) return;

        // لا نحفظ اشتراكاً قديماً مرة أخرى. نهجره أولاً.
        if (!samePushApplicationKey(subscription, VAPID_PUBLIC_KEY)) {
            await ensureCurrentVapidSubscription();
            return;
        }

        await saveSubscriptionToSupabase(subscription);
    } catch (err) {
        console.warn("Failed to refresh push subscription language:", err);
    }
}

async function subscribeToPush() {
    if (!("serviceWorker" in navigator) || !("PushManager" in window)) {
        return null;
    }

    try {
        const registration = await navigator.serviceWorker.ready;
        const permission = await Notification.requestPermission();

        if (permission !== "granted") {
            console.warn("Notification permission:", permission);
            return null;
        }

        let subscription = await registration.pushManager.getSubscription();

        if (subscription && !samePushApplicationKey(subscription, VAPID_PUBLIC_KEY)) {
            const oldEndpoint = subscription.endpoint;

            await deleteSubscriptionFromSupabase(oldEndpoint).catch(() => {});
            await subscription.unsubscribe().catch(() => {});
            subscription = null;
        }

        if (!subscription) {
            subscription = await registration.pushManager.subscribe({
                userVisibleOnly: true,
                applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY)
            });
        }

        const saved = await saveSubscriptionToSupabase(subscription);

        if (!saved) {
            console.error(
                "Push subscription exists on device but could not be saved to Supabase."
            );
            return null;
        }

        localStorage.setItem(PUSH_VAPID_MARKER_KEY, VAPID_PUBLIC_KEY);
        localStorage.setItem(PUSH_ENABLED_KEY, "1");

        updateBadge(0);
        sendPushLanguageToServiceWorker();

        return subscription;
    } catch (err) {
        console.warn("Push subscription failed:", err);
        return null;
    }
}

async function saveSubscriptionToSupabase(subscription) {
    const SUPABASE_ANON_KEY =
        "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImtubGVlaGpqZWpmZW9iY21wd253Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODQwMjk1NzAsImV4cCI6MjA5OTYwNTU3MH0.Q5Peb8CXDYNSPtQJGK6meij4vFRfOUq9qFz4rHBXE8E";

    try {
        let profile = {};

        try {
            profile = JSON.parse(
                localStorage.getItem("x2_profile") || "{}"
            );
        } catch (_) {}

        const p256dh = subscription.getKey("p256dh");
        const auth = subscription.getKey("auth");

        if (!subscription.endpoint || !p256dh || !auth) {
            console.error("Invalid push subscription:", subscription);
            return false;
        }

        const payload = {
            endpoint: subscription.endpoint,
            p256dh: btoa(
                String.fromCharCode(...new Uint8Array(p256dh))
            ),
            auth: btoa(
                String.fromCharCode(...new Uint8Array(auth))
            ),
            user_phone: normalizeUaePhone(profile.phone || ""),
            user_email: String(
                profile.email ||
                profile.authEmail ||
                ""
            ).trim().toLowerCase(),
            user_lang: getCurrentPushLanguage(),
            created_at: new Date().toISOString()
        };

        const commonHeaders = {
            apikey: SUPABASE_ANON_KEY,
            Authorization: "Bearer " + SUPABASE_ANON_KEY,
            "Content-Type": "application/json"
        };

        // PATCH أولاً إذا كان الـendpoint موجوداً، ثم POST لو غير موجود.
        const patchResponse = await fetch(
            "https://knleehjjejfeobcmpwnw.supabase.co/rest/v1/push_subscriptions?endpoint=eq." +
                encodeURIComponent(subscription.endpoint),
            {
                method: "PATCH",
                headers: {
                    ...commonHeaders,
                    Prefer: "return=representation"
                },
                body: JSON.stringify(payload)
            }
        );

        if (patchResponse.ok) {
            const patched = await patchResponse.json().catch(() => []);
            if (Array.isArray(patched) && patched.length > 0) {
                return true;
            }
        }

        const postResponse = await fetch(
            "https://knleehjjejfeobcmpwnw.supabase.co/rest/v1/push_subscriptions",
            {
                method: "POST",
                headers: {
                    ...commonHeaders,
                    Prefer: "resolution=merge-duplicates,return=minimal"
                },
                body: JSON.stringify(payload)
            }
        );

        if (!postResponse.ok) {
            console.error(
                "Failed to save push subscription:",
                postResponse.status,
                await postResponse.text().catch(() => "")
            );
            return false;
        }

        return true;
    } catch (err) {
        console.warn("Failed to save subscription:", err);
        return false;
    }
}

async function unsubscribeFromPush() {
    if (!("serviceWorker" in navigator)) return;

    try {
        const registration = await navigator.serviceWorker.ready;
        const subscription = await registration.pushManager.getSubscription();

        if (subscription) {
            await deleteSubscriptionFromSupabase(subscription.endpoint).catch(() => {});
            await subscription.unsubscribe();
        }

        localStorage.removeItem(PUSH_VAPID_MARKER_KEY);
        localStorage.setItem(PUSH_ENABLED_KEY, "0");

        clearBadge();
    } catch (err) {
        console.warn("Failed to unsubscribe from push:", err);
    }
}

function updateBadge(count) {
    if ("setAppBadge" in navigator) {
        if (count > 0) {
            navigator.setAppBadge(count).catch(() => {});
        } else {
            navigator.clearAppBadge().catch(() => {});
        }
    }

    const badge = document.getElementById("mobNotifBadge");

    if (badge) {
        if (count > 0) {
            badge.textContent = count > 99 ? "99+" : count;
            badge.style.display = "";
        } else {
            badge.style.display = "none";
        }
    }
}

function clearBadge() {
    updateBadge(0);

    navigator.serviceWorker?.controller?.postMessage({
        type: "CLEAR_BADGE"
    });
}

async function getPushStatus() {
    if (!("serviceWorker" in navigator) || !("PushManager" in window)) {
        return "unsupported";
    }

    if (Notification.permission === "denied") {
        return "denied";
    }

    try {
        const registration = await navigator.serviceWorker.ready;
        const subscription = await registration.pushManager.getSubscription();

        if (!subscription) return "unsubscribed";

        if (!samePushApplicationKey(subscription, VAPID_PUBLIC_KEY)) {
            return "stale";
        }

        return "subscribed";
    } catch (err) {
        console.warn("Failed to check push status:", err);
        return "unsubscribed";
    }
}

async function initPushButton() {
    const buttons = document.querySelectorAll("#push-subscribe-btn");
    if (!buttons.length) return;

    const enabledText =
        "&#128276; &#1605;&#1601;&#1593;&#1604; &#10003;";

    const enableText =
        "&#128277; &#1578;&#1601;&#1593;&#1610;&#1604; &#1575;&#1604;&#1573;&#1588;&#1593;&#1575;&#1585;&#1575;&#1578;";

    function renderButton(enabled, text) {
        buttons.forEach(button => {
            button.disabled = false;
            button.style.display = "inline-flex";
            button.style.opacity = "";
            button.innerHTML = text || (enabled ? enabledText : enableText);
            button.style.background = enabled ? "#27ae60" : "";
            button.style.color = enabled ? "#fff" : "";
        });
    }

    // قبل عرض حالة الزر حاول هجرة أي اشتراك قديم تلقائياً.
    await ensureCurrentVapidSubscription().catch(() => {});

    const status = await getPushStatus();

    if (status === "unsupported") {
        const text =
            "&#128276; &#1575;&#1604;&#1573;&#1588;&#1593;&#1575;&#1585;&#1575;&#1578; &#1594;&#1610;&#1585; &#1605;&#1583;&#1593;&#1608;&#1605;&#1577; &#1593;&#1604;&#1609; &#1607;&#1584;&#1575; &#1575;&#1604;&#1605;&#1578;&#1589;&#1601;&#1581;";

        buttons.forEach(button => {
            button.disabled = true;
            button.style.display = "inline-flex";
            button.style.opacity = ".75";
            button.innerHTML = text;
        });

        return;
    }

    if (status === "subscribed") {
        renderButton(
            true,
            "&#128276; &#1575;&#1604;&#1573;&#1588;&#1593;&#1575;&#1585;&#1575;&#1578; &#1605;&#1601;&#1593;&#1604;&#1577;"
        );
    } else {
        renderButton(false, enableText);
    }

    buttons.forEach(button => {
        button.onclick = async () => {
            const currentStatus = await getPushStatus();

            if (currentStatus === "subscribed") {
                await unsubscribeFromPush().catch(() => {});
                renderButton(false, enableText);
                return;
            }

            buttons.forEach(btn => {
                btn.disabled = true;
                btn.innerHTML = "&#9203;...";
            });

            const subscription = await subscribeToPush();

            if (subscription) {
                renderButton(true, enabledText);
            } else {
                renderButton(false, enableText);
            }
        };
    });
}

(async () => {
    await registerSW();

    // الهجرة التلقائية تتكرر بأمان عند فتح أي صفحة تحمل الملف.
    await ensureCurrentVapidSubscription().catch(() => {});

    await initPushButton();

    clearBadge();

    try {
        const unread = JSON.parse(
            localStorage.getItem("x2_notifications") || "[]"
        ).filter(item => !item.read).length;

        if (unread > 0) {
            updateBadge(unread);
        } else {
            clearBadge();
        }
    } catch (_) {
        clearBadge();
    }
})();
